INSERT INTO TB_EOS_EXC_REQ (
    EXC_REQ_ID, RESOURCE_ID, REQ_ORG_CD, REQ_USER_ID, REQ_DTM, START_YMD, END_YMD,
    REASON_TXT, BLOCKER_TXT, MITIGATION_TXT, FINAL_PLAN_TXT, FINAL_TARGET_YMD,
    MONTHLY_CHECK_YN, EXIT_CRITERIA_TXT, STATUS_CD, REG_USER_ID, REG_DTM
) VALUES (
    #{excReqId}, #{resourceId}, #{reqOrgCd}, #{reqUserId}, #{reqDtm}, #{startYmd}, #{endYmd},
    #{reasonTxt}, #{blockerTxt}, #{mitigationTxt}, #{finalPlanTxt}, #{finalTargetYmd},
    #{monthlyCheckYn}, #{exitCriteriaTxt}, #{statusCd}, #{regUserId}, #{regDtm}
)

INSERT INTO TB_EOS_EXC_APPR (
    APPR_ID, EXC_REQ_ID, DECISION_CD, CONDITION_TXT, REJECT_REASON_TXT,
    APPROVER_ID, APPROVE_DTM, EXTEND_OF_APPR_ID, REG_USER_ID, REG_DTM
) VALUES (
    #{apprId}, #{excReqId}, #{decisionCd}, #{conditionTxt}, #{rejectReasonTxt},
    #{approverId}, #{approveDtm}, #{extendOfApprId}, #{regUserId}, #{regDtm}
)

INSERT INTO TB_EOS_MONTHLY_CHK (
    CHECK_ID, EXC_REQ_ID, CHECK_YM, MITIGATION_OK_YN, RESIDUAL_RISK_TXT, PLAN_PROGRESS_TXT,
    ISSUE_TXT, NEXT_CHECK_YMD, CHECKER_ID, CHECK_DTM, REG_USER_ID, REG_DTM
) VALUES (
    #{checkId}, #{excReqId}, #{checkYm}, #{mitigationOkYn}, #{residualRiskTxt}, #{planProgressTxt},
    #{issueTxt}, #{nextCheckYmd}, #{checkerId}, #{checkDtm}, #{regUserId}, #{regDtm}
)

mapper.select:
SELECT * FROM TB_EOS_MONTHLY_CHK
 WHERE 1=1
AND EXC_REQ_ID = #{excReqId}
AND CHECK_YM = #{checkYm}
 ORDER BY CHECK_YM DESC
